arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_1943_01.json') as f:
    data = json.load(f)

# Search for unemployment trust fund entries
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'unemployment' in k.lower():
                print(f'{path}.{k}: {v}')
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search(item, f'{path}[{i}]')

search(data)
"
